const packs=[
{title:'Begin with the Roman Road',refs:['Romans 3:10','Romans 3:23','Romans 5:8','Romans 6:23','Romans 10:9','Romans 10:13','John 3:16','Ephesians 2:8','1 John 1:9','Acts 16:31']},
{title:'Assurance in Christ',refs:['John 5:24','John 10:28','Romans 8:1','Romans 8:28','Romans 8:38','Philippians 1:6','1 John 5:11','1 John 5:13','Hebrews 13:5','1 Peter 1:5']},
{title:'Trust and Wisdom',refs:['Proverbs 3:5','Proverbs 3:6','Psalm 23:1','Psalm 46:1','Psalm 119:11','James 1:5','Isaiah 41:10','Matthew 6:33','Psalm 37:4','Proverbs 16:3']},
{title:'Prayer and Peace',refs:['Philippians 4:6','Philippians 4:7','Matthew 6:9','Matthew 6:10','Matthew 6:11','Matthew 6:12','Matthew 6:13','1 Thessalonians 5:17','Psalm 4:8','Jeremiah 33:3']},
{title:'Love and Service',refs:['John 13:34','John 13:35','1 Corinthians 13:4','1 Corinthians 13:5','1 Corinthians 13:6','1 Corinthians 13:7','Galatians 5:22','Galatians 5:23','Micah 6:8','Matthew 22:39']},
{title:'Words of Jesus',refs:['John 14:6','John 14:27','Matthew 5:16','Matthew 11:28','Matthew 11:29','Luke 6:31','John 8:12','John 15:5','Matthew 28:19','Matthew 28:20']},
{title:'Hope and Courage',refs:['Joshua 1:9','Psalm 27:1','Psalm 34:8','Psalm 34:18','Isaiah 40:31','Romans 12:12','2 Timothy 1:7','Deuteronomy 31:6','Psalm 56:3','John 16:33']},
{title:'The Gospel',refs:['John 1:1','John 1:14','John 3:17','Romans 5:1','Romans 5:8','Romans 6:23','2 Corinthians 5:17','2 Corinthians 5:21','Ephesians 2:8','Ephesians 2:9']},
{title:'Faithful Living',refs:['Romans 12:1','Romans 12:2','Galatians 2:20','Colossians 3:2','Colossians 3:23','Hebrews 11:1','Hebrews 12:1','James 1:22','1 Peter 5:7','1 John 4:19']},
{title:'Mission and Witness',refs:['Matthew 5:14','Matthew 5:16','Matthew 28:19','Matthew 28:20','Mark 16:15','Acts 1:8','Romans 1:16','2 Corinthians 5:20','1 Peter 3:15','Psalm 96:3']}
];
const $=id=>document.getElementById(id);let round=[],q=0,score=0,answered=false,translation='KJV',direction='text';
$('pack').innerHTML=packs.map((p,i)=>'<option value="'+i+'">Set '+(i+1)+' · '+p.title+'</option>').join('');
async function getText(ref){const url='https://bible-api.com/'+encodeURIComponent(ref)+'?translation=kjv';const res=await fetch(url);if(!res.ok)throw new Error('Passage service unavailable');const d=await res.json();return (d.text||'').trim().replace(/\s+/g,' ')}
const bibleBooks={'Romans':'ROM','John':'JHN','Ephesians':'EPH','Acts':'ACT','1 John':'1JN','Philippians':'PHP','Hebrews':'HEB','1 Peter':'1PE','Proverbs':'PRO','Psalm':'PSA','James':'JAS','Matthew':'MAT','1 Thessalonians':'1TH','Jeremiah':'JER','1 Corinthians':'1CO','Galatians':'GAL','Micah':'MIC','Isaiah':'ISA','2 Timothy':'2TI','Deuteronomy':'DEU','2 Corinthians':'2CO','Colossians':'COL','Mark':'MRK'};
function bibleUrl(ref){const m=ref.match(/^(.+?)\s+(\d+):(\d+)$/);if(!m)return 'https://www.bible.com/bible/59';return 'https://www.bible.com/bible/59/'+(bibleBooks[m[1]]||'JHN')+'.'+m[2]+'.'+m[3]+'.ESV'}
function setControls(disabled){$('setup').querySelectorAll('input,select,button').forEach(x=>x.disabled=disabled)}
async function start(){translation=document.querySelector('[name=translation]:checked').value;direction=document.querySelector('[name=direction]:checked').value;if(translation==='ESV'){direction='ref';$('setup').querySelector('[name=direction][value=ref]').checked=true}const idx=Number($('pack').value);$('setup').hidden=true;$('result').hidden=true;$('quiz').hidden=false;$('quiz').innerHTML='<p>Opening the passages…</p>';setControls(true);try{round=await Promise.all(packs[idx].refs.map(async ref=>({ref,text:await getText(ref)})));round=round.filter(x=>x.text);if(round.length<4)throw new Error('Not enough passages loaded for this set.');q=0;score=0;show()}catch(e){$('quiz').innerHTML='<h2>Could not load the verses</h2><p>'+e.message+'. Check the connection and try the set again.</p><button class="primary" id="back">Back to setup</button>';document.getElementById('back').onclick=()=>{$('quiz').hidden=true;$('setup').hidden=false;setControls(false)}}}
function show(){answered=false;const item=round[q];const picks=[item,...round.filter((x,i)=>i!==q).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);let prompt='',answers=[];if(direction==='text'&&translation==='KJV'){prompt='<b>'+item.ref+'</b>';answers=picks.map(x=>({label:x.text,correct:x.ref===item.ref}))}else{prompt='<b>'+item.text+'</b>';answers=picks.map(x=>({label:x.ref,correct:x.ref===item.ref}))}if(translation==='ESV')prompt+=' <a target="_blank" rel="noopener" href="'+bibleUrl(item.ref)+'">Read this passage in ESV ↗</a>';const setNo=Number($('pack').value)+1;$('quiz').innerHTML='<div class="meta"><span>SET '+setNo+' · QUESTION '+(q+1)+' OF '+round.length+' · '+translation+'</span><span>SCORE '+score+'</span></div><div class="progress"><span style="width:'+((q/round.length)*100)+'%"></span></div><h2>'+(direction==='text'&&translation==='KJV'?'Choose the correct verse text':'Choose the reference')+'</h2><p class="question">'+prompt+'</p><div class="options">'+answers.map((a,i)=>'<button class="option" data-i="'+i+'">'+a.label+'</button>').join('')+'</div><p class="status" id="status" role="status" aria-live="polite"></p>';document.querySelectorAll('.option').forEach((b,i)=>b.onclick=()=>choose(b,answers[i]));}
function choose(btn,a){if(answered)return;answered=true;document.querySelectorAll('.option').forEach(b=>b.disabled=true);btn.classList.add(a.correct?'correct':'wrong');if(a.correct){score++;$('status').textContent='Correct — keep going.'}else{$('status').textContent='Not quite. The right answer is '+round[q].ref+'.'}setTimeout(()=>{q++;if(q<round.length)show();else finish()},850)}
function finish(){$('quiz').hidden=true;$('result').hidden=false;$('result').innerHTML='<p class="eyebrow">SET COMPLETE</p><h2>'+packs[Number($('pack').value)].title+'</h2><p>You scored</p><strong>'+score+' / '+round.length+'</strong><p>Review the passages, then repeat the set to strengthen recall.</p><button class="primary" id="again">Repeat this set</button> <button class="primary" id="next">Next set</button><button class="primary" id="settings">Change settings</button>';document.getElementById('again').onclick=start;document.getElementById('next').onclick=()=>{$('pack').value=String((Number($('pack').value)+1)%packs.length);start()};document.getElementById('settings').onclick=()=>{$('result').hidden=true;$('setup').hidden=false;setControls(false)}}
$('start').onclick=start;
